export function createEvent(id='live',mode:EventData['mode']='live'):EventData {const seed=crypto.randomUUID();return {id,mode,title:CASE_TITLE,phase:1,phaseStartedAt:Date.now(),promptDeadline:null,participants:[],facilitators:[],suspects:[],submissions:[],evidenceIds:[],dialogue:[],avatar:{x:16,y:10},controllerId:null,pollOpen:false,votes:{},revealed:false,secret:null,testLog:[],publishedSnapshotId:null,ownerProviderId:null,createdAt:Date.now(),turn:0,dialogueArchive:[],narrativeSeed:seed,opening:initialOpening(seed),story:null};}
