function evidenceText(e:EventData,id:string){
 const slot=Math.max(0,e.suspects.findIndex(x=>x.id===e.secret?.killerId));
 const p=getCaseAccessProfile(narrativeSeed(e),slot);
 const data:Record<string,{description:string;significance:string}>={
  watch:{description:'The glass is cracked. Its final pulse reading and stopped display agree: 21:17. The corridor alarm began at 21:19.',significance:'The collapse preceded the alarm by two minutes. A timestamp does not identify a person.'},
  flask:{description:'A thin violet film remains in Dr. Sen’s trial flask. Reagent V-17 is absent from the restricted cabinet. Its effect takes approximately three minutes.',significance:'Compare the preparation interval with the watch. The residue does not identify who handled it.'},
  logs:{description:'The write-once backup records the audit visitor entering the restricted laboratory at 21:12 using '+p.clearance+' clearance. The surviving entry has no personal name or badge number.',significance:'Several staff members share this clearance. Compare their access profiles with the other two records.'},
  camera:{description:'A continuous corridor sequence follows the same 21:12 audit visitor. The badge has a '+p.badgeMark+' marking; the face and other badge details are obscured. The visitor leaves immediately after the 21:17 collapse.',significance:'The stripe narrows the candidates, but does not identify one person. Match it with the clearance and the appointment docket.'},
  note:{description:'The folded appointment slip for that laboratory visit specifies a '+p.docketGroup+' audit docket. It reads: “21:10. Lab. Bring the altered trial results before I submit the audit.” No personal addressee is written.',significance:'The docket group explains the audit meeting. Several suspects share it; combine this detail with the access log and camera marking.'},
 };
 if(isShootingCase(e)){
  data.watch={description:'The glass is cracked. The stopped display and final pulse reading mark 21:17, the time of the gunshot. The corridor alarm began at 21:19.',significance:'The shot preceded the alarm by two minutes. The watch establishes time, not identity.'};
  data.flask={description:'A thin violet film remains in the trial flask. It is reagent V-17, used in the disputed research. Dr. Sen died from a gunshot, not the flask’s contents.',significance:'This is a research-process clue. Reagent handling alone does not identify the shooter.'};
  data.camera={description:'A continuous corridor sequence follows the same 21:12 audit visitor. The badge has a '+p.badgeMark+' marking; the face and other badge details are obscured. That visitor leaves the lab immediately after the 21:17 gunshot, before anyone else enters.',significance:'The stripe is only one partial identifier. Intersect it with the clearance in the access log and the audit docket on the appointment slip.'};
 }
 return data[id]??{description:'',significance:''};
}
